import { useState } from 'react';

type FilterLabel = 'All' | 'Active' | 'Archived' | 'Starred';

const FILTERS: FilterLabel[] = ['All', 'Active', 'Archived', 'Starred'];

// Owns only visual pressed state; grid filtering is not wired.
const chipStyles = `
@layer components {
  .chip-bar {
    display: flex;
    gap: var(--shelf-space-sm);
    flex-wrap: wrap;
  }

  .chip {
    appearance: none;
    display: inline-flex;
    align-items: center;
    padding: var(--shelf-space-xs) var(--shelf-space-md);
    border-radius: var(--shelf-radius-full);
    border: var(--shelf-borderWidth-thin) solid var(--shelf-chip-borderColor-rest);
    background-color: var(--shelf-chip-bgColor-rest);
    color: var(--shelf-chip-fgColor-rest);
    font-family: var(--shelf-font-family-base);
    font-size: var(--shelf-font-size-sm);
    font-weight: var(--shelf-font-weight-medium);
    cursor: pointer;
  }

  .chip[aria-pressed="true"] {
    background-color: var(--shelf-chip-bgColor-pressed);
    color: var(--shelf-chip-fgColor-pressed);
    border-color: var(--shelf-chip-borderColor-pressed);
  }

  .chip:focus-visible {
    outline: var(--shelf-focusRing);
    outline-offset: var(--shelf-focusRing-offset);
  }
}
`;

export function ChipFilter(): JSX.Element {
  const [pressed, setPressed] = useState<FilterLabel>('All');

  return (
    <>
      <style>{chipStyles}</style>
      <div className="chip-bar" role="group" aria-label="Filter">
        {FILTERS.map((label) => (
          <button
            key={label}
            type="button"
            className="chip"
            aria-pressed={pressed === label}
            onClick={() => setPressed(label)}
          >
            {label}
          </button>
        ))}
      </div>
    </>
  );
}
